BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/jiuwudaishi-119-april-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002799；EPUB电子本，纸本及异文待核", "id": "bffcd1c8-8ce4-571f-a132-8838a0f5b90a"}, {"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/jiuwudaishi-119-june-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002801；EPUB电子本，纸本及异文待核", "id": "e90d7a2f-c277-5e4e-82d8-8c92e03d9797"}, {"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/jiuwudaishi-119-may-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002800；EPUB电子本，纸本及异文待核", "id": "29ee8211-c4ac-549b-9af7-ca29e34fcc8f"}, {"title": "辽史·卷六", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/liaoshi-6-april-959/source.txt", "note": "《辽史》卷六，段落 liaoshi-7cd182a20e67-p000691；EPUB电子本，纸本及异文待核", "id": "b48ad146-4b0b-5959-be80-df7f9d0da1a7"}, {"title": "辽史·卷六", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/liaoshi-6-may-959/source.txt", "note": "《辽史》卷六，段落 liaoshi-7cd182a20e67-p000692；EPUB电子本，纸本及异文待核", "id": "4414b688-4835-5635-9e1d-95ab31bccfaf"}, {"title": "宋史·巻二百七十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/songshi-273-yaoneibin-surrender/source.txt", "note": "《宋史》巻二百七十三，段落 songshi-9c6e46fee832-p059116；EPUB电子本，纸本及异文待核", "id": "1afc1008-5d2a-5346-9244-a0edb0e867b7"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/052a8074ed5386bf0e6e93afa0652e5c64213b7e/content/books/zizhi-tongjian/vol-294/year-0959/part-02/sources/library/tongjian-294-959-north-return/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003493；电子底本待考，分段待核", "id": "369bb07b-44cd-5100-9c00-fe3945faf928"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/tongjian-294-959-spring/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003492；电子底本待考，分段待核", "id": "a02ac045-90ba-56a9-8fb0-e5bbd0c3d25b"}, {"title": "旧五代史·卷一百十九", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/jiuwudaishi-119-march-959/source.txt", "note": "《旧五代史》卷一百十九，段落 jiu-wudaishi-205deb4a7860-p002798；EPUB电子本，纸本及异文待核", "id": "70e7c49f-699d-570e-a3eb-c0c0e559fb77"}, {"title": "新五代史·卷十二", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/d7f52d562d203b2a0ae571237b8530fe83e02856/content/books/zizhi-tongjian/vol-294/year-0959/part-01/sources/library/xinwudaishi-12-959/source.txt", "note": "《新五代史》卷十二，段落 xin-wudaishi-b08f244b9241-p000381；EPUB电子本，纸本及异文待核", "id": "46ccc53b-5a04-5228-9747-031d9ca3c3a8"}, {"title": "宋史·卷271·张藏英传", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a03e158968cf63490b7ea1d52bdaea928e33b44d/content/books/zizhi-tongjian/vol-291/year-0953/part-03/sources/library/songshi-271-zhangcangying/source.txt", "note": "《宋史》卷271·张藏英传，段落 songshi-9c6e46fee832-p058967；已核上下文及传主，纸本及异文待核。", "id": "8edcec80-faf6-5c90-95af-0feefd563eee"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "孙行友", "aliases": ["孫行友"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "与孙方简聚众于狼山，借孙深意的术及边民避乱扩展部众。《宋史》记为莫州清苑人，出身务农，后任孙方谏的副手；《资治通鉴》记为孙方简之弟，《宋史》却记孙方谏为他的兄子，亲属与籍贯表述分别保留待核。生卒年未核。", "biography": null, "status": "draft", "id": "297fda14-1470-5546-b76b-7b2461eb1d3d"}, {"name": "吴廷祚", "aliases": ["吳廷祚", "吴延祚", "吳延祚"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字庆之，并州太原人，早年为郭威亲校。959年二月以宣徽南院使身份与韩通督发丁夫浚汴水。新旧《五代史》又作吴延祚，按相同使职与留守任务关联，保留姓名异文。生卒年本段未核。", "biography": null, "status": "draft", "id": "8bc98a15-7a90-5881-b0f2-dd8e47a9d791"}, {"name": "张美", "aliases": ["張美"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "清河人，后周枢密院承旨。《通鉴》记955年六月任右领军大将军、权点检三司事，《旧五代史》记八月任权判三司，任职月与称号差异分别保留。早年管理澶州隶属三司的财物，曾应柴荣私人所求而供给，郭威得知后将他调到濮州。", "biography": null, "status": "draft", "id": "e0ae365f-4a51-5f92-82eb-86e617f0d42b"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "萧思温", "aliases": ["蕭思溫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹南京留守。《辽史》记应历九年四月戊戌，任兵马都总管应对后周北征。所载任命并不证明当日已击退后周，生卒年本段未核。", "biography": null, "status": "draft", "id": "ef9e0261-5cd2-5095-a942-94e405cd5fd9"}, {"name": "王洪（契丹宁州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹宁州刺史。959年四月壬辰，柴荣北征至乾宁军时，他以城归降后周。以职务限定姓名，不与其他同名人物混同，生卒年未载。", "biography": null, "status": "draft", "id": "8b9241ad-c9a8-523e-a888-4f9641abbaaf"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "终廷晖", "aliases": ["終廷暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹益津关守将。959年四月辛丑，柴荣北征到益津关时，他以城归降后周。《旧五代史》相关句为注文引《通鉴》，不算独立出处印证。生卒年未载。", "biography": null, "status": "draft", "id": "6832868f-99c4-5633-974c-7d2b4aff3255"}, {"name": "姚内斌", "aliases": ["姚內斌"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "平州卢龙人，曾任契丹关西巡检、瓦桥关使。959年四月癸卯赵匡胤先至瓦桥关时，他以城归降后周。《宋史》记所率五百人，并称后周任他为汝州刺史；该书还记姓名后来因避讳改用今名，原名未在此段完整写出。生卒年未核。", "biography": null, "status": "draft", "id": "8e3461d9-2e6a-5900-8a83-91d21c5a838b"}, {"name": "刘楚信", "aliases": ["劉楚信"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹莫州刺史。959年四月甲辰以城归降后周，《旧五代史》州名作鄚州。同一职务和归降行动的字形差别保留，不另建一人。生卒年未载。", "biography": null, "status": "draft", "id": "3b13ec19-3703-52f5-9c06-66e6ca9ae05a"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "高彦晖", "aliases": ["高彥暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，契丹瀛州刺史。959年五月乙巳朔以城归降后周。当前通鉴月字作正月，新旧五代史均记五月，原字保留并说明。生卒年未载。", "biography": null, "status": "draft", "id": "bc5546f3-16da-5208-9702-02543f7bbfc9"}, {"name": "刘重进（后周先锋都指挥使）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周先锋都指挥使。959年五月丙午，柴荣命他先出发，前往固安。与早期契丹通事刘重进是否同人尚无足够证据，分别保存。生卒年未载。", "biography": null, "status": "draft", "id": "c7c42d68-0759-5a0c-bda2-f053a3515473"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "刘承钧", "aliases": ["劉承鈞", "刘钧", "劉鈞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "刘崇的次子。951年父亲在晋阳称帝时，任侍卫亲军都指挥使、太原尹。《旧五代史》也记他是刘崇之子并任两职。生卒年本批未录。", "biography": null, "status": "draft", "id": "3f4681a7-ca79-5d5d-a5c2-53bef1936681"}, {"name": "李在钦", "aliases": ["李在欽"], "era": "五代十国", "birth_year": null, "death_year": 959, "description": "契丹易州刺史。959年五月戊申，孙行友奏报攻下易州、擒李在钦；李在钦被献至军中并遭斩首。生年未载，奏报日期不能直接当作实际被俘日。", "biography": null, "status": "draft", "id": "f2788e69-700b-5e32-b2da-7a1bbc5d0054"}, {"name": "张藏英", "aliases": ["張藏英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "涿州范阳人，契丹军使，兼任榷盐制置等职。953年率军士、亲属、盐户等归附后周。《通鉴》电子本户台与旧史卢台、宋传盧䑓写法有别，按同人同役保留校核说明。生卒年留待后续逐段补录。", "biography": null, "status": "draft", "id": "f4a79754-77c7-514a-a927-bc9d261e9a40"}, {"name": "韩令坤", "aliases": ["韓令坤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "磁州武安人，后周侍卫马军都指挥使。955年十一月，奉柴荣命与其他十一名将领随李谷、王彦超出征南唐。生卒年未载。", "biography": null, "status": "draft", "id": "808ffe02-5578-55cc-8c1f-2b9823cfd253"}, {"name": "陈思让", "aliases": ["陳思讓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋作坊使，幽州人。941年十一月受石重贵派遣讨伐安从进，丁丑获任先锋军监军。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "59feec41-432b-5d18-829a-46def9523238"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "张丕", "aliases": ["張丕", "张丕旦", "張丕旦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉辽州刺史。959年六月乙亥朔李筠奏报攻下辽州、俘获张丕。《旧五代史》作张丕旦，按同日同职同战关联姓名异文；该书还记戊子部送俘虏并获释。生卒年未载。", "biography": null, "status": "draft", "id": "fd71465e-6c1b-5e36-af18-0dc6dc630f88"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
